CREATE DATABASE IF NOT EXISTS height_site CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE height_site;
CREATE TABLE IF NOT EXISTS admins(id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS offers(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200) NOT NULL,description TEXT,image_url VARCHAR(1024),link_url VARCHAR(1024),sort_order INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS posts(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200) NOT NULL,slug VARCHAR(200) NOT NULL UNIQUE,excerpt TEXT,body LONGTEXT,image_url VARCHAR(1024),sort_order INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reviews(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,author VARCHAR(160) NOT NULL,quote TEXT NOT NULL,sort_order INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS videos(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200),video_url VARCHAR(1024),thumbnail_url VARCHAR(1024),sort_order INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS inquiries(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,type VARCHAR(40) NOT NULL,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(20) NOT NULL,service VARCHAR(120),preferred_date DATE NULL,message TEXT NOT NULL,status ENUM('new','handled') DEFAULT 'new',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS settings(`key` VARCHAR(100) PRIMARY KEY,`value` TEXT);
